<header class="panel-page-heading"><div><span>Meus indicados</span><h1><?= e($owner['nome']) ?></h1><p>Resumo comercial e chácaras vinculadas.</p></div><a class="btn btn-outline" href="<?= url('/afiliado/indicados') ?>">Voltar</a></header>
<section class="panel-card affiliate-owner-card"><div class="panel-card-heading"><h2>Proprietário</h2></div><dl class="admin-detail-list affiliate-owner-details"><div><dt>Nome</dt><dd><?= e($owner['nome']) ?></dd></div><div><dt>E-mail</dt><dd><?= e($owner['email']) ?></dd></div><div><dt>Telefone</dt><dd><?= e($owner['telefone']?:'-') ?></dd></div><div><dt>Cadastro</dt><dd><?= e($date($owner['data_cadastro'])) ?></dd></div><div><dt>Indicação</dt><dd><?= e($date($owner['afiliado_atribuido_em'])) ?></dd></div><div><dt>Origem</dt><dd><?= e($origin[$owner['afiliado_origem']]??'Indicação') ?></dd></div></dl></section>
