<section class="panel-card"><div class="panel-card-heading"><h2>Chácaras</h2></div><?php if(!$owner['chacaras_lista']):?><div class="empty-preview"><span aria-hidden="true">&#8962;</span><div><strong>Nenhuma chácara cadastrada</strong><p>As chácaras deste proprietário aparecerão aqui.</p></div></div><?php else:?><div class="responsive-table"><table class="panel-table"><thead><tr><th scope="col">Nome</th><th scope="col">Localização</th><th scope="col">Aprovação</th><th scope="col">Operação</th><th scope="col">Mensalidade</th><th scope="col">Pagamentos com comissão</th><th scope="col">Comissão acumulada</th></tr></thead><tbody><?php foreach($owner['chacaras_lista']as$c):?><tr><td><strong><?= e($c['nome']) ?></strong></td><td><?= e(trim($c['cidade'].(!empty($c['estado'])?' / '.$c['estado']:''))) ?></td><td><span class="status-pill"><?= e(ucfirst($c['status_aprovacao'])) ?></span></td><td><?= e(ucfirst($c['status_operacional'])) ?></td><td><?= e($labels[$c['mensalidade_status']]??ucfirst(strtolower(str_replace('_',' ',$c['mensalidade_status'])))) ?></td><td><?= (int)$c['pagamentos_comissao'] ?></td><td><?= e($money((int)$c['comissao_centavos'])) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
